use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn main(){let root=Path::new("/tmp/zopro-fft-pass-grain");let perf=read(root.join("perf/result.json"));assert_eq!(perf["status"],"complete");assert_eq!(perf["distinct_verified_exports"],93);let preflight=read(root.join("preflight/result.json"));assert_eq!(preflight["status"],"complete");assert_eq!(preflight["steps"].as_array().unwrap().len(),38);let rows=read(root.join("perf/rows.json"));assert_eq!(rows.as_array().unwrap().len(),93);let sdk:usize=rows.as_array().unwrap().iter().map(|r|r["samples_ms"].as_array().unwrap().len()+3).sum();assert_eq!(sdk,3516);let mut samples=0u64;let mut captures=0;for r in rows.as_array().unwrap(){assert_eq!(r["summary"]["priming"],3);let w=r["summary"]["workers"].as_u64().unwrap();assert_eq!(w,if r["case"]=="1x2-w16"{16}else{32});if r["phase"]=="profile"{assert_eq!(r["profile"]["lost_records"],0);assert_eq!(r["profile"]["sampled_pids"].as_array().unwrap().len(),1);samples+=r["profile"]["samples"].as_u64().unwrap();captures+=1;}}assert_eq!(captures,9);assert_eq!(samples,239637);
let template=read(root.join("all-nine-template.json"));let fixture:BTreeMap<String,String>=template["cases"].as_array().unwrap().iter().map(|c|(Path::new(c["image"].as_str().unwrap()).file_stem().unwrap().to_str().unwrap().into(),c["public_sha256"].as_str().unwrap().into())).collect();let prior:BTreeSet<String>=serde_json::from_value(template["prior_proof_sha256"].clone()).unwrap();assert_eq!(prior.len(),2934);let mut seen=BTreeSet::new();let mut all=BTreeMap::new();for(name,value)in read(root.join("preflight-proof-inventory.json")).as_object().unwrap(){assert_eq!(hash(name),value.as_str().unwrap());all.insert(name.to_owned(),value.as_str().unwrap().to_owned());}for(name,value)in read(root.join("perf/proof-inventory.json")).as_object().unwrap(){let path=root.join("perf").join(name);assert_eq!(hash(&path),value.as_str().unwrap());all.insert(path.to_str().unwrap().to_owned(),value.as_str().unwrap().to_owned());}assert_eq!(all.len(),222);for(name,digest)in &all{let p=Path::new(name);if p.extension().is_some_and(|e|e=="proof"){assert!(!prior.contains(digest));assert!(seen.insert(digest.to_owned()));assert!(all.contains_key(p.with_extension("public").to_str().unwrap()));}else{assert_eq!(p.extension().unwrap(),"public");let stem=p.parent().unwrap().file_name().unwrap().to_str().unwrap();assert_eq!(&fixture[stem],digest);}}assert_eq!(seen.len(),111);
for name in ["core-off","core-on"]{let tests=read(root.join("native").join(name).join("tests.json"));assert!(!tests.is_null());let stdout=fs::read_to_string(root.join("native").join(name).join("stdout.log")).unwrap();assert!(stdout.contains("111 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));}
verify_receipts(root,&rows,&preflight);let source=fs::read_to_string(root.join("candidate/crates/zopro-core/src/fft/pair.rs")).unwrap();let original=fs::read_to_string("/home/ubuntu/src/zk-tools/zopro/crates/zopro-core/src/fft/pair.rs").unwrap();let recovered=source.split("\n// Bound only the cheap independent FFT packing/product passes.").next().unwrap().replace("\n    #[cfg(zopro_fft_pass_grain)]\n    if fft_pass_grain_enabled() { return euler_product_grained(plan, a, b); }","");assert_eq!(recovered,original);let product=|s:&str|{let begin=s.find("pub(super) fn euler_product_study(").unwrap();let end=s[begin..].find("\n// Rejoin two packed pairs").unwrap()+begin;s[begin..end].to_owned()};let begin=source.find("fn euler_product_grained(").unwrap();let end=source[begin..].find("\n#[cfg(any(zopro_fft_pass_grain,test))]").unwrap()+begin;let restored=source[begin..end].replace("fn euler_product_grained(","pub(super) fn euler_product_study(").replace(".with_min_len(32)","").replace("euler_combine_grained(&mut a, &b, &values);","euler_combine_products(&mut a, &b, &values);");assert_eq!(restored.trim(),product(&original).trim());
let pilot=read(root.join("pilot-result.json"));assert_eq!(pilot["performance_gate_passed"],false);let closed=json!({"status":"closed; fixed local screen rejected","adopted":false,"goal_achieved":false,"sdk_requests":sdk+72,"distinct_gnark_exports":seen.len(),"proof_public_members":all.len(),"profile_captures":captures,"profile_samples":samples,"lost_records":0,"prior_identities":prior.len(),"compiled_source_pins":172,"performance_pins":452,"native_core_off":111,"native_core_on":111,"raw_tests":2,"cubic_tests":6,"field_tests":"unchanged kernels; inherited33, not newly executed","disabled_source_recovered_byte_identically":true,"on_product_recovers_original_except_adapters_and_helper_dispatch":true,"conclusion":"Primary32 improves against both controls, but physical16 observations are highly variable across all variants; the fixed screen fails16 nonregression and four-case aggregate against accepted. Preserve all observations; no unchanged rerun or AWS launch. No universal/default adoption.","failed_checks":pilot["failed_checks"],"limitations":"No new portable, concurrent SDK, pressure, large-circuit or target-host qualification. Small-stack concurrent kernel tests are not concurrent whole-proof qualification. RSS is whole process and not minimum RAM.","memory":"No new buffer/table/point copy/per-proof allocation; fixed iterator grouping may still affect other allocation overlap.","owned_aws_resources":0});
fs::write(root.join("proof-inventory.json"),format!("{}\n",serde_json::to_string_pretty(&all).unwrap())).unwrap();fs::write(root.join("closeout.json"),format!("{}\n",serde_json::to_string_pretty(&closed).unwrap())).unwrap();println!("CLOSED_VERIFIED SDK{} EXPORTS{} PROFILES{captures} SAMPLES{samples}",sdk+72,seen.len());}
fn verify_receipts(root:&Path,rows:&Value,preflight:&Value){
    fn check(dir:&Path){let exit=read(dir.join("exit.json"));assert_eq!(exit["success"],true);assert_eq!(exit["returncode"],0);for stream in ["stdout","stderr"]{assert_eq!(hash(dir.join(format!("{stream}.log"))),exit[format!("{stream}_sha256")].as_str().unwrap());}}
    for name in preflight["steps"].as_array().unwrap(){let name=name.as_str().unwrap();let dir=root.join("preflight").join(name);check(&dir);if name.ends_with("-verify"){assert!(fs::read_to_string(dir.join("stdout.log")).unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));}}
    for row in rows.as_array().unwrap(){let dir=root.join("perf").join(row["phase"].as_str().unwrap()).join(format!("b{}",row["block"].as_u64().unwrap())).join(row["case"].as_str().unwrap()).join(row["variant"].as_str().unwrap());check(&dir.join("run"));check(&dir.join("verify"));assert!(fs::read_to_string(dir.join("verify/stdout.log")).unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));if row["phase"]=="profile"{check(&dir.join("symbols"));}}
}
